from mk import *
STRICT["on"] = True
from lib import mini

def fig():
    g = Fig(560, 250, "יוסי מחזיק סלסילה עם מתקן קפיצי שמקפיץ כדור כלפי מעלה, וגרפים 1 עד 4 (מהירות-זמן) ו-5 עד 8 (מקום-זמן)")
    g.ground(20, 200, 190)
    g.person(80, 190, 1.9)
    g.poly([(120, 108), (160, 108), (140, 138)], fill="var(--d-fill)")
    g.ball(140, 50, 7)
    g.line(60, 138, 200, 138, stroke="var(--d-dim)", width=1, dash="3 3")
    g.text(204, 142, "y = 0", cls="dim", anchor="start")
    g.add('<line x1="140" y1="150" x2="140" y2="20" stroke="var(--d-line)" stroke-width="1.4" marker-end="url(#f-axis)"/>')
    g.text(148, 24, "y", anchor="start")
    g.heb(80, 212, "יוסי")
    vs = [("1", dict(pts=[(0, 0.8), (0.5, 0), (1, 0.8)])), ("2", dict(pts=[(0, 0.8), (1, -0.8)], neg=True)), ("3", dict(pts=[(0, 0), (0.5, 0.8), (1, 0)])),
          ("4", dict(fn=lambda u: 0.55 * (1 - (1 - 2 * u) ** 2) if u < 0.5 else 0.55 + 0.35 * (2 * u - 1) ** 2))]
    for i, (lab, kw) in enumerate(vs):
        mini(g, 250 + i * 78, 90 if lab != "2" else 70, 58, 50 if lab != "2" else 40, label=lab, yl="v", **kw)
    ys = [("5", dict(fn=lambda u: 0.55 * (1 - (1 - 2 * u) ** 2) if u < 0.5 else 0.55 + 0.4 * (2 * u - 1) ** 2)), ("6", dict(pts=[(0, 0), (0.5, 0.8), (1, 0)])),
          ("7", dict(fn=lambda u: 3.2 * u * (1 - u))), ("8", dict(neg=True, segs=[(lambda u: 1.6 * u * (1 - u) * 1.6, 0, 0.45), (lambda u: -1.8 * (u - 0.55) ** 2 * 2.2, 0.55, 1)]))]
    for i, (lab, kw) in enumerate(ys):
        mini(g, 250 + i * 78, 210 if lab != "8" else 196, 58, 50 if lab != "8" else 36, label=lab, yl="y", **kw)
    return g

E(id="bagrut-2005-q1", year=2005, label="2005 שאלה 1", topic="kinematics", sub="kin-free-fall", diff=2, fig=fig,
  stem=r"יוסי משחק בצעצוע שמורכב מסלסילה, שבה כדור קטן, ובתחתיתה מתקן קפיצי. לחיצה על המתקן הקפיצי מקפיצה את הכדור כלפי מעלה. הכדור מגיע לגובה של $2.45\,\text{m}$ מעל תחתית הסלסילה, ונופל בחזרה לתוך הסלסילה. כדי לנתח את תנועת הכדור הוגדר ציר מקום $y$ שכיוונו החיובי כלפי מעלה וראשיתו בתחתית הסלסילה. $t = 0$ הוא הרגע שבו הכדור מתחיל את תנועתו. הזנח את התנגדות האוויר, את אורך הקפיץ ואת מסת הסלסילה.",
  parts=[
    P("א", r"התלמידים התבקשו לסרטט באופן איכותי גרף של מהירות הכדור כפונקציה של הזמן, מרגע $t = 0$ עד שהוא שב לתחתית הסלסילה. התקבלו ארבעה סוגים של גרפים. איזה מבין הגרפים 1-4 מתאר נכון את התנועה? הסבר.", choice(["1", "2", "3", "4"], 1), ["graph", "signs"], [
        X(r"הכיוון החיובי נקבע בשאלה: כלפי מעלה. בתנועה בהשפעת הכובד בלבד התאוצה קבועה ושלילית, ולכן גרף המהירות הוא קו ישר אחד עם שיפוע שלילי."),
        S(r"משוואת המהירות", r"התאוצה היא תאוצת הכובד, ולכן מציבים אותה במקום התאוצה, עם מינוס כי היא כלפי מטה", r"v = v_0 + (-g)\,t", eq=r"v = v_0 + at"),
        S(r"פוסלים את גרף 1 ואת גרף 3", r"יש בהם שבירה, כלומר התאוצה משתנה באמצע. בגרף 1 גם המהירות לא מחליפה סימן, אף שהכדור חוזר למטה", r"a = -g"),
        S(r"פוסלים את גרף 4", r"הוא עקום, כלומר התאוצה משתנה, והמהירות בו לא מתאפסת בשיא", r"v_{\max h} = 0"),
        S(r"גרף 2", r"קו ישר שיורד מערך חיובי, חוצה את האפס בשיא, וממשיך לערכים שליליים בירידה", r"v = v_0 - g t"),
    ], r"גרף 2", key=r"גרף 2"),
    P("ב", r"התלמידים התבקשו לסרטט באופן איכותי גרף של מקום הכדור כפונקציה של הזמן, מרגע $t = 0$ עד שהוא שב לתחתית הסלסילה. איזה מבין הגרפים 5-8 מתאר נכון את התנועה? הסבר.", choice(["5", "6", "7", "8"], 2), ["graph"], [
        S(r"משוואת המקום", r"הכדור יוצא מהראשית. זו פרבולה הפוכה, שמתחילה ונגמרת בגובה אפס", r"y = 0 + v_0 t + \tfrac{1}{2}(-g)\,t^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"פוסלים את שאר הגרפים", r"גרף 6 בנוי מקווים ישרים, כלומר מהירות קבועה. גרף 5 לא חוזר לאפס. בגרף 8 יש קפיצה, והוא נגמר מתחת לסלסילה", r"y(0) = y(t_2) = 0"),
    ], r"גרף 7", key=r"גרף 7"),
    P("ג", r"חשב את זמן התנועה של הכדור, מרגע $t = 0$ עד שהוא שב לתחתית הסלסילה.", num(1.4, "s"), ["principle", "algebra"], [
        X(r"מוצאים את זמן הירידה מהשיא. העלייה לוקחת בדיוק אותו זמן, כי התנועה סימטרית."),
        S(r"משוואת המקום בירידה מהשיא", r"בשיא המהירות אפס. לירידה נוח לבחור כלפי מטה כחיובי, והראשית בשיא. התאוצה היא תאוצת הכובד", r"2.45 = 0 + 0 \cdot t_1 + \tfrac{1}{2} \cdot 10 \cdot t_1^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"מבודדים את הזמן", r"מחלקים בחמש ומוציאים שורש", r"t_1^2 = \frac{2.45}{5} = 0.49 \;\Rightarrow\; t_1 = 0.7\,\text{s}"),
        S(r"הזמן הכולל", r"העלייה לוקחת אותו זמן כמו הירידה", r"t = 2 \cdot 0.7 = 1.4\,\text{s}"),
    ], r"$1.4\,\text{s}$", key=r"1.4 s"),
    P("ד", r"יוסי ממשיך לשחק בצעצוע שלו כשהוא נוסע על גלגיליות בכיוון אופקי ימינה, במהירות קבועה של $3\,\text{m/s}$. האם גם במקרה הזה הכדור שהוקפץ כלפי מעלה ייפול בחזרה לתוך הסלסילה? הסבר.", choice(["כן", "לא"], 0), ["understanding", "principle"], [
        S(r"המהירות האופקית של הכדור", r"הכדור יוצא מהסלסילה עם המהירות שלה, ימינה, ולא פועל עליו כוח אופקי שישנה אותה", r"v_{x,1} = v_2 = 3\,\text{m/s}"),
        S(r"מסקנה", r"הכדור והסלסילה מתקדמים יחד אופקית, ולכן הכדור נמצא כל הזמן מעל הסלסילה", r"\Delta x = 3t - 3t = 0"),
    ], r"כן: לכדור ולסלסילה אותה מהירות אופקית", key=r"כן"),
    P("ה", r"ברגע שהכדור הגיע לשיא הגובה, יוסי עצר ועמד במקומו. חשב את המרחק האופקי של הכדור מתחתית הסלסילה כשהוא הגיע ל-$y = 0$.", num(2.1, "m"), ["principle", "algebra"], [
        S(r"מה קורה מהשיא", r"הכדור ממשיך ימינה באותה מהירות אופקית, אבל הסלסילה נעצרה", r"v_x = 3\,\text{m/s},\qquad v_2 = 0"),
        S(r"זמן הירידה", r"מצאנו בסעיף ג. העצירה של יוסי לא משפיעה על התנועה האנכית של הכדור", r"t_1 = 0.7\,\text{s}"),
        S(r"המרחק", r"בזמן הירידה הכדור מתקדם אופקית במהירות קבועה, והסלסילה עומדת", r"\Delta x = 0 + 3 \cdot 0.7 = 2.1\,\text{m}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
    ], r"$2.1\,\text{m}$", key=r"2.1 m"),
  ],
  concepts=["זריקה אנכית", "גרפים של מהירות ומקום", "תאוצה קבועה", "מהירות אופקית של גוף משוחרר"],
  summary=r"כדור שקופץ מסלסילה וחוזר אליה. בחירת גרפים נכונים, זמן מעוף, ומה קורה כשהסלסילה זזה או עוצרת.",
  review="הנחה שלי.\nגרפי האפשרויות 1 עד 8 שורטטו מחדש לפי המקור.\nמה לבדוק: רק לאשר.")
